+					version: 1,
+					statements: [
+						"CREATE TABLE migration_first (value TEXT) STRICT",
+						"INSERT INTO migration_first (value) VALUES ('retained')",
+					],
+				},
+				{
+					version: 2,
+					statements: ["CREATE TABLE migration_second (value TEXT) STRICT", "THIS IS NOT SQL"],
+				},
